pub fn promote(
    current: &str,
    candidate: &str,
    checks_ok: bool,
    ready: bool,
) -> (String, bool) {
    if !candidate.trim().is_empty()
        && candidate != current
        && checks_ok
        && ready
    {
        (candidate.to_owned(), true)
    } else {
        (current.to_owned(), false)
    }
}

fn main() {
    assert_eq!(
        promote("v1", "v2", true, true),
        ("v2".to_owned(), true),
        "case 1"
    );
    assert_eq!(
        promote("v1", "", true, true),
        ("v1".to_owned(), false),
        "case 2"
    );
    assert_eq!(
        promote("v1", "v2", true, false),
        ("v1".to_owned(), false),
        "case 3"
    );
    assert_eq!(
        promote("v1", "v2", false, true),
        ("v1".to_owned(), false),
        "case 4"
    );
    assert_eq!(
        promote("v1", "v1", true, true),
        ("v1".to_owned(), false),
        "case 5"
    );
    println!("worked example passed");
}

